package main
import("fmt";"reflect";"strings";"github.com/minz/minzc/pkg/hir";"github.com/minz/minzc/pkg/mir2";"github.com/minz/minzc/pkg/nanz")
const source=`fun region_eq(src:^u8,arena:^u8,src_start:u16,arena_ptr:u16,len:u8)->u8 {var i:u8=0 while i<len {if src[src_start+i]!=arena[arena_ptr+1+i] {return 0} i=i+1} return 1}`
func main(){a,e:=nanz.Parse(source,"review.nanz");must(e);b,e:=nanz.Parse(source,"review.nanz");must(e);must(hir.ApplyRegionComparePrototype(b,"region_eq"));mods:=[]*mir2.Module{hir.LowerModule(a),hir.LowerModule(b)};count:=0
layouts:=[][4]int64{{0,1024,0,0},{1,0,0,0},{0,0,0,65535},{65535,1024,0,0},{0,65535,65535,0},{65000,64000,600,1534},{100,200,65535,65535}}
for n:=int64(0);n<256;n++ {for _,args:=range layouts {for mismatch:=int64(-1);mismatch<n;mismatch++ {heap:=make([]byte,65536);for j:=range heap {heap[j]=7};if mismatch>=0{right:=uint16(args[1]+int64(uint16(args[3]+1+mismatch)));heap[right]=9};verify(mods,args,n,heap);count++}}}
fmt.Printf("PASS full64k equality/mismatch/wrap/alias domain %d cases\n",count)
for heapSize:=16;heapSize<=32;heapSize++ {for _,side:=range []int{0,1} {for n:=int64(0);n<5;n++ {args:=[4]int64{0,0,0,65535};if side==0{args[0]=int64(heapSize-1)}else{args[1]=int64(heapSize-1)};heap:=make([]byte,heapSize);for i:=range heap{heap[i]=7};verify(mods,args,n,heap);count++}}}
fmt.Printf("PASS independent sequential modular oracle %d cases; every u8 length/mismatch position, wrap/alias layouts and first/second/tail traps; exact ordered successful loads/error/fullheap\n",count)
}
func must(e error){if e!=nil{panic(e)}}
func verify(mods []*mir2.Module,args [4]int64,n int64,heap []byte){want:=int64(1);events:=[]mir2.VMDataAccess{};trap:="";for i:=int64(0);i<n;i++{left:=int(uint16(args[0]+int64(uint16(args[2]+i))));right:=int(uint16(args[1]+int64(uint16(args[3]+1+i))));if left>=len(heap){trap=fmt.Sprintf("load: out-of-bounds address %d (heap size %d)",left,len(heap));break};events=append(events,mir2.VMDataAccess{Op:mir2.OpLoad,Addr:int64(left),Value:heap[left]});if right>=len(heap){trap=fmt.Sprintf("load: out-of-bounds address %d (heap size %d)",right,len(heap));break};events=append(events,mir2.VMDataAccess{Op:mir2.OpLoad,Addr:int64(right),Value:heap[right]});if heap[left]!=heap[right]{want=0;break}}
for version,m:=range mods{vm:=mir2.NewVM(m);vm.EnsureHeap(int64(len(heap)));vm.WriteHeapSlice(0,heap);got:=[]mir2.VMDataAccess{};vm.ObserveDataAccess=func(a mir2.VMDataAccess){got=append(got,a)};r,e:=vm.Call("region_eq",[]mir2.Value{{I:args[0]},{I:args[1]},{I:args[2]},{I:args[3]},{I:n}});err:="";if e!=nil{err=e.Error();if k:=strings.Index(err,"load: ");k>=0{err=err[k:]}};if err!=trap||!reflect.DeepEqual(events,got)||!reflect.DeepEqual(vm.ReadHeap(0,len(heap)),heap)||(e==nil&&!reflect.DeepEqual(r,[]mir2.Value{{I:want}})){panic(fmt.Sprintf("version%d n%d args%v want%d trap%s got%v %v",version,n,args,want,trap,r,e))}}}
